theme_css:
:root{--red:#DC0120;--red-ink:#A8001A;--ink:#0E1627;--paper:#FFFFFF;--soft:#F4F5F8;--r:18px}
body{background:var(--paper);color:var(--ink)}
.bar,.trust,section:has(.doors),section:has(.steps),section:has(.proof),section.close,.hero::before{display:none!important}
.nav{background:#fff;border-bottom:1px solid #E6E8EE}
.nav .in{padding-block:10px}
.nav .brand img{height:52px;width:auto}
.nav .links a{color:var(--ink);font-weight:600}
.nav .links a.call{background:var(--ink);color:#fff;border-radius:999px;padding:9px 16px}
.hero{background:linear-gradient(180deg,#0E1627 0%,#15213B 100%);color:#fff}
.hero-grid{grid-template-columns:1fr;max-width:640px;margin:0 auto;gap:22px;padding-block:40px 56px;text-align:center}
.hero-copy .eyebrow,.hero-copy .k{color:#FF5A6E;letter-spacing:.14em;font-size:12px;font-weight:700;text-transform:uppercase}
.hero-copy h1{font-family:var(--display);font-size:clamp(30px,6.2vw,44px);line-height:1.1;margin:10px 0 12px}
.hero-copy p,.hero-copy .lede{font-size:17px;line-height:1.55;color:#C9D0DE;margin:0 auto;max-width:560px}
.chips{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;list-style:none;padding:0;margin:16px 0 0}
.chips li,.chips span,.chip{background:transparent;border:1.5px solid rgba(255,255,255,.55);color:#fff;border-radius:999px;padding:7px 14px;font-size:13px;font-weight:600}
.hero-copy .ctas{display:none}
.card{border-radius:var(--r);padding:22px;box-shadow:0 18px 50px rgba(0,0,0,.28);border:0;text-align:left}
.card-head .k{color:var(--red);letter-spacing:.12em;text-transform:uppercase;font-size:12px;font-weight:700}
.card-head .count{color:#6B7280;font-size:13px}
.door-row{border-radius:14px;padding:14px 12px;border:1.5px solid #E6E8EE;margin:8px 0}
.door-row .n{background:var(--soft);color:var(--ink);font-weight:700}
.door-row b{font-size:17px}
.door-row small{color:#6B7280}
.door-row.primary{background:var(--red);border-color:var(--red);padding:18px 14px}
.door-row.primary:hover{background:var(--red-ink)}
.cta,.btn.gold{background:var(--red);color:#fff;border-radius:14px;box-shadow:none}
.cta:hover,.btn.gold:hover{background:var(--red-ink)}
.cta.alt{color:#fff;border-color:rgba(255,255,255,.6)}
.prog i{background:var(--red)}
.opts button{border-radius:14px;padding:16px 48px 16px 16px;font-size:17px}
.opts button:hover,.opts button:focus-visible{border-color:var(--red);background:#FFF5F6}
.opts button::after{color:var(--red)}
.q h2,.q h3{font-family:var(--display);font-size:22px;line-height:1.25}
.fine{color:#6B7280;font-size:13px}
footer,.foot{background:var(--soft);color:#4B5563}
footer .in,.foot .in{max-width:760px;margin:0 auto;text-align:center;font-size:13px;line-height:1.55}
footer img,.foot img{height:44px;width:auto;margin:0 auto 10px;display:block}
footer a,.foot a{color:var(--ink)}
.firm-disclaimer{text-align:left}
@media(max-width:640px){.nav .links a:not(.call){display:none}.nav .brand img{height:44px}.card{padding:18px}}
